script:
def walk(path):
    out = []
    for name in repo.list(path):
        p = path + "/" + name if path != "." else name
        if name.endswith("/"):
            out.extend(walk(p.rstrip("/")))
        else:
            out.append(p)
    return out

src_files = walk("src")
changed = []
for p in src_files:
    content = repo.read(p)
    if "V1_TAG" in content:
        repo.write(p, content.replace("V1_TAG", "V2_TAG"))
        changed.append(p)

remaining = repo.search("V1_TAG")
return {
  "src_files": src_files,
  "changed": changed,
  "remaining_v1": ["%s:%d" % (h.path, h.line) for h in remaining],
  "diff": repo.diff(),
}
